import{c as e,Q as n,j as o,m as s}from"./chunks/framework.BqPkuuVc.js";const a="/assets/station-configuration.By733Jiz.png",m=JSON.parse('{"title":"Station configuration","description":"","frontmatter":{},"headers":[],"relativePath":"user/reference/station-configuration.md","filePath":"user/reference/station-configuration.md"}'),r={name:"user/reference/station-configuration.md"};function i(h,t,d,g,c,l){return n(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="station-configuration" tabindex="-1">Station configuration <a class="header-anchor" href="#station-configuration" aria-label="Permalink to &quot;Station configuration&quot;">​</a></h1><p><strong>Audience:</strong> Whoever prepares the SportIdent units before an event: setting each unit&#39;s code and mode, its switch-off time, its clock and AIR+ (contactless) settings.</p><p>How to read a SportIdent station&#39;s settings, change them, and program a whole box of units one after another.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><p>The same as for <a href="./../running-the-event/station-memory#what-you-need">reading a station&#39;s memory</a>:</p><ul><li>A SportIdent USB station (a BSM7 or BSM8) plugged into this computer. Manager calls it the <strong>direct station</strong>.</li><li>The <strong>coupling rod</strong>, to connect it to the unit you&#39;re setting up, which Manager calls the <strong>remote station</strong>.</li><li>A browser with Web Serial: Chrome, Edge, or Firefox 151 or later.</li></ul><p>You don&#39;t need an event. Open <strong>Station configuration</strong> from the <strong>USB</strong> icon at the top of the <strong>Events</strong> list (hover over the icons to find it).</p><p><strong>It&#39;s the same reader card download uses.</strong> If the station is already connected for card download, it&#39;s connected here too, and disconnecting here disconnects card download as well. Configure units before the event or away from the download desk, not while cards are being downloaded.</p><h2 id="reading-a-station" tabindex="-1">Reading a station <a class="header-anchor" href="#reading-a-station" aria-label="Permalink to &quot;Reading a station&quot;">​</a></h2><p><img src="'+a+'" alt="The Station configuration panel, connected: Remote station and Direct station, a Switch the station off after writing switch, and the Read and Batch mode buttons"></p><ol><li><strong>Connect the reader</strong>, if it isn&#39;t already (<strong>Connected</strong> shows at the top of the panel).</li><li>Choose which station to talk to: <ul><li><strong>Remote station</strong> — the unit on the coupling rod. This is the usual choice.</li><li><strong>Direct station</strong> — the USB station itself, for example to check its firmware or set its mode.</li></ul></li><li>Put the unit on the coupling rod and click <strong>Read</strong>.</li></ol><p>Manager shows two more columns:</p><ul><li><strong>Settings</strong> — what you can change (see below).</li><li>What the station reports, which can&#39;t be changed here: <ul><li><strong>Station</strong> — serial number, product (such as BSF8), board version, firmware, boot version and when it was made;</li><li><strong>Protocol</strong> — its operating mode and code, its communication settings (such as <strong>Handshake</strong> and <strong>192 records from an SI Card 6</strong>), its switch-off time and when its settings were last changed — and, for a unit with a display, whether it is upside-down;</li><li><strong>Battery</strong> — when the battery was fitted, its capacity, how much has been used, its voltage and temperature. A USB station has no battery, so this card isn&#39;t shown for one;</li><li><strong>Memory</strong> — the size of its backup memory, how many records it holds, and how full it is. A count shown as <strong>≥</strong> means the memory has filled and started again from the beginning, so it holds at least that many.</li></ul></li></ul><p>Anything the station didn&#39;t report, or Manager couldn&#39;t read, shows as <strong>Not known</strong>.</p><h3 id="the-station-clock" tabindex="-1">The station clock <a class="header-anchor" href="#the-station-clock" aria-label="Permalink to &quot;The station clock&quot;">​</a></h3><p>For a station with a battery, the <strong>Station clock</strong> section shows its time, ticking, and how far it is from this computer&#39;s (<strong>Drift vs PC</strong>: <strong>In sync</strong>, or seconds ahead or behind). <strong>Read at</strong> says when the station was read, so you can tell an old reading from a fresh one.</p><p>Click <strong>Set to PC time</strong> to set it. There&#39;s no confirmation, because setting the clock to the right time is always safe. Every station that will punch should be in sync before the event: a control whose clock is out puts the wrong time on every punch it records. If one went out with its clock wrong, a <a href="./../event-setup/controls-and-radio-controls#time-offset">Time Offset</a> on that control corrects every punch it recorded.</p><h2 id="changing-the-settings" tabindex="-1">Changing the settings <a class="header-anchor" href="#changing-the-settings" aria-label="Permalink to &quot;Changing the settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Operating mode</strong></td><td>What the unit does: <strong>CN - Control</strong>, <strong>STA - Start</strong>, <strong>FIN - Finish</strong>, <strong>CHK - Check</strong>, <strong>CLR - Clear</strong>, the beacon (AIR+) modes such as <strong>BC CN - Beacon Control</strong>, and the SIAC modes (<strong>SIAC on</strong>, <strong>SIAC off</strong>, <strong>SIAC battery test</strong>, and so on). Only the modes this unit accepts are listed. The names are SportIdent&#39;s own, as on the unit and in its software.</td></tr><tr><td><strong>Station code</strong></td><td>The control code the unit punches with. Some modes fix it, such as the SIAC modes, and the field is then greyed out with <em>Fixed by the operating mode.</em></td></tr><tr><td><strong>Auto increment</strong></td><td>After a successful write, add one to <strong>Station code</strong>, ready for the next unit. Handy when setting out a sequence of controls (31, 32, 33…).</td></tr><tr><td><strong>Switch off after (minutes)</strong></td><td>How long the unit stays awake after its last use. Between 2 minutes and just under 4 days; the time is shown in hours and minutes beneath.</td></tr><tr><td><strong>Beep</strong>, <strong>Flash</strong></td><td>Whether the unit beeps and flashes when punched.</td></tr><tr><td><strong>Extended protocol</strong>, <strong>Auto-send</strong>, <strong>Sprint mode</strong>, <strong>Stop when the memory is full</strong></td><td>SportIdent&#39;s own settings, as in its software. A setting a mode doesn&#39;t allow is greyed out.</td></tr><tr><td><strong>AIR+ radio</strong>, <strong>AIR+ timing</strong></td><td>Only for the beacon modes: whether the unit sends punches over AIR+ radio (<strong>Off</strong>, <strong>Send the last punch</strong>, <strong>Send every punch</strong>, <strong>Send every unsent punch</strong>) and its AIR+ timing.</td></tr></tbody></table><p>To write them:</p><ol><li>Change what you need. A setting you leave alone keeps the value the station has.</li><li>Click <strong>Write</strong>. Manager lists the settings it will write. <strong>Check the operating mode and the station code</strong>: the station keeps them until somebody changes them.</li><li>Confirm. For a station with a battery, its clock is set to this computer&#39;s time as well.</li></ol><p>Manager then reads the station back and reports <strong>The station was written, and read back to confirm it</strong> only if the read-back matches. If it doesn&#39;t, it says which part didn&#39;t take: read the station again before using it.</p><p><strong>Switch the station off after writing</strong> turns the unit off once it&#39;s been written, so it isn&#39;t left awake on the bench running down its battery. It applies to the remote station only, and is remembered on this computer.</p><blockquote><p><strong>Note:</strong> The settings go onto whichever unit is on the coupling rod when you click <strong>Write</strong>, which may not be the one you read. That&#39;s how you set up several units the same way: read one, change the settings, then swap the unit and write again. For a whole box of units, use batch mode.</p></blockquote><h2 id="programming-many-units-batch-mode" tabindex="-1">Programming many units: batch mode <a class="header-anchor" href="#programming-many-units-batch-mode" aria-label="Permalink to &quot;Programming many units: batch mode&quot;">​</a></h2><p>Batch mode writes the same settings to unit after unit with no clicking in between. You put a unit on the coupling rod, take it off once it&#39;s switched off, and put the next one on.</p><ol><li><p>Click <strong>Batch mode</strong>.</p></li><li><p>Tick each setting to write, and set its value:</p><ul><li><strong>Operating mode</strong>;</li><li><strong>AIR+ radio</strong> (only once the mode is a beacon mode);</li><li><strong>Switch off after (minutes)</strong>.</li></ul><p>A setting you don&#39;t tick is left as each unit has it. <strong>The station code is never changed</strong>, so every control keeps its own number. To number a run of units one after another (31, 32, 33…), use <strong>Write</strong> with <strong>Auto increment</strong> instead.</p></li><li><p>Click <strong>Start</strong>. Manager shows <em>Waiting for a unit…</em>.</p></li><li><p>Put a unit on the coupling rod. Manager writes it, checks it, sets its clock, and switches it off. Switching off is how Manager knows to move on.</p></li><li><p>Take it off and put the next one on.</p></li><li><p>Click <strong>Stop</strong> when you&#39;re done.</p></li></ol><p>The list shows each unit&#39;s product and code with what happened: <strong>Written and time set to</strong> a time, <strong>Failed</strong>, a reason it refused, or a warning that its clock couldn&#39;t be set. <strong>Units written</strong> counts the successes. A unit that fails doesn&#39;t stop the run: take it off, put the next one on, and deal with the failed one afterwards. A unit written in a contact mode can&#39;t take an AIR+ radio setting, and says so.</p><h2 id="when-a-station-won-t-take-the-settings" tabindex="-1">When a station won&#39;t take the settings <a class="header-anchor" href="#when-a-station-won-t-take-the-settings" aria-label="Permalink to &quot;When a station won&#39;t take the settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>What it means</th></tr></thead><tbody><tr><td><strong>meshO cannot configure this product.</strong></td><td>Manager can read it but not write it: SportIdent configures that product differently. Use SportIdent Config+.</td></tr><tr><td><strong>…firmware version that is not a number…</strong></td><td>Manager can&#39;t tell which layout the station uses, so it writes nothing. Use SportIdent Config+.</td></tr><tr><td><strong>This product does not offer that operating mode on firmware…</strong> / <strong>…does not list that operating mode…</strong></td><td>Choose another mode, or update the unit&#39;s firmware with SportIdent&#39;s software.</td></tr><tr><td><strong>…set to control code…, which meshO cannot write back.</strong></td><td>Writing would renumber the unit. Use SportIdent Config+.</td></tr><tr><td><strong>The station did not answer in time.</strong></td><td>Check the unit is seated on the coupling rod and awake, and try again.</td></tr><tr><td><strong>The station&#39;s reply was damaged in transit.</strong></td><td>Check the cable and try again.</td></tr><tr><td><strong>The settings were written, but the station clock could not be set.</strong></td><td>Click <strong>Set to PC time</strong> before the unit goes out.</td></tr></tbody></table><p>For the errors the reader itself reports, such as the direct station left in an unknown mode, see <a href="./../running-the-event/station-memory#when-something-goes-wrong">Station memory</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../running-the-event/station-memory">Station memory</a></li><li><a href="./sportident-cards">SportIdent cards</a></li><li><a href="./../running-the-event/card-download">Card download</a></li><li><a href="./sportident-usb-on-macos">SportIdent USB stations on macOS</a></li><li><a href="./../event-setup/pre-event-checklist">Pre-event checklist</a></li></ul>',33)])])}const f=e(r,[["render",i]]);export{m as __pageData,f as default};
